export function getCountryByCode(code?: string): CountryDirectoryItem | undefined {
  if (!code) return undefined;
  const upper = code.trim().toUpperCase();
  return COUNTRIES.find((c) => c.cca2 === upper || c.cca3 === upper);
}

export function getCountryByName(name?: string): CountryDirectoryItem | undefined {
  if (!name) return undefined;
  const lower = name.trim().toLowerCase();
  return COUNTRIES.find(
    (c) =>
      c.name.toLowerCase() === lower ||
      c.officialName.toLowerCase() === lower ||
      lower.includes(c.name.toLowerCase()) ||
      c.name.toLowerCase().includes(lower)
  );
}

export function searchCountries(
  query: string,
  continent: ContinentFilter = 'All',
  sortOrder: 'asc' | 'desc' = 'asc'
): CountryDirectoryItem[] {
  const cleanQuery = query.trim().toLowerCase();

  let filtered = COUNTRIES.filter((country) => {
    const matchesContinent = continent === 'All' || country.continent === continent;
    if (!matchesContinent) return false;

    if (!cleanQuery) return true;

    const matchesName = country.name.toLowerCase().includes(cleanQuery);
    const matchesOfficial = country.officialName.toLowerCase().includes(cleanQuery);
    const matchesCapital = country.capital.toLowerCase().includes(cleanQuery);
    const matchesCca2 = country.cca2.toLowerCase().includes(cleanQuery);
    const matchesCca3 = country.cca3.toLowerCase().includes(cleanQuery);
    const matchesCurrency = country.currencies.some(
      (curr) =>
        curr.code.toLowerCase().includes(cleanQuery) || curr.name.toLowerCase().includes(cleanQuery)
    );

    return matchesName || matchesOfficial || matchesCapital || matchesCca2 || matchesCca3 || matchesCurrency;
  });

  filtered.sort((a, b) => {
    const cmp = a.name.localeCompare(b.name);
    return sortOrder === 'asc' ? cmp : -cmp;
  });

  return filtered;
}
